    int optimized_value;
    void execute() { /* Specific integer logic */ }
    void special_int_method() {}
};

// Full Specialization for T=bool
template <>
struct MyClass<bool> {
    // Highly optimized storage (e.g., bitfield)
    unsigned char bit : 1;
    void execute() { /* Specific boolean logic */ }
};
